// A throwaway consumer app, generated by tools/verify-consumer/android.sh outside the repository.
// It is deliberately NOT a composite build of android/: the point is to resolve the SDK the way a
// customer's app does, from Maven Central, so a missing artefact, a POM that names a module that
// was never uploaded, or a metadata mismatch fails here.
pluginManagement {
    repositories {
        google()
        mavenCentral()
        gradlePluginPortal()
    }
}

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    // Exactly the two repositories the README tells an integrator to have. Adding mavenLocal(),
    // a snapshot repository or the Sonatype staging URL would let a broken release pass.
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "verify-consumer"
include(":app")
